import type { CatalogueEntry, CatalogueMatch, PlatformId } from './types';
import { crc32Hex } from './hash';

/**
 * Offline ROM fingerprint catalogue.
 *
 * Data is generated by scripts/fetch-dats.mjs from the No-Intro DATs mirrored in
 * libretro/libretro-database (CC-BY-SA-4.0). It contains titles + hashes only.
 *
 * Runtime representation is a per-platform Map keyed by `size:crc32`, because
 * that lookup is O(1) and needs no hashing beyond CRC32, which we already
 * compute for every upload. SHA-1 confirms matches when present.
 */

export interface CataloguePlatformData {
  schemaVersion: 1;
  platform: PlatformId;
  generatedAt: string;
  datVersion: string | null;
  datName: string;
  datSize: number;
  count: number;
  source: {
    repository: string;
    path: string;
    commitBlob: string;
    dataset: string;
    licence: string;
    licenceUrl: string;
    attribution: string;
  };
  entries: Array<{ c: string; s: number; h?: string; t: string; r: string; v: string; k: 'c' | 'h' }>;
}

export interface CatalogueIndex {
  schemaVersion: 1;
  generatedAt: string;
  source: { repository: string; branch: string; dataset: string; licence: string; licenceUrl: string; note: string };
  entries: Array<{
    platform: PlatformId;
    file: string;
    count: number;
    bytes: number;
    datVersion: string | null;
    datBlob: string;
    licence: string;
  }>;
}

interface LoadedPlatform {
  data: CataloguePlatformData;
  map: Map<string, CatalogueEntry>;
}

/** Assets are served relative to the deployment base (`import.meta.env.BASE_URL`). */
const catalogueBase = `${(import.meta.env.BASE_URL ?? '/').replace(/\/$/, '')}/data/catalogue`;

const cache = new Map<PlatformId, LoadedPlatform | null>();
const pending = new Map<PlatformId, Promise<LoadedPlatform | null>>();

const key = (size: number, crc: string) => `${size}:${crc.toUpperCase()}`;

async function loadPlatform(platform: PlatformId, baseUrl = catalogueBase): Promise<LoadedPlatform | null> {
  const isDefaultBase = baseUrl === catalogueBase;
  if (isDefaultBase && cache.has(platform)) return cache.get(platform)!;
  const url = `${baseUrl}/${platform}.json`;
  try {
    const res = await fetch(url, { credentials: 'same-origin' });
    if (!res.ok) {
      if (isDefaultBase) cache.set(platform, null);
      return null;
    }
    const data = (await res.json()) as CataloguePlatformData;
    const map = new Map<string, CatalogueEntry>();
    for (const row of data.entries) {
      map.set(key(row.s, row.c), {
        id: `${platform}:${row.s}:${row.c}`,
        platform,
        title: row.t,
        region: row.r,
        version: row.v,
        kind: row.k === 'h' ? 'homebrew' : 'commercial',
        licence: null,
        source: `${data.source.dataset} · ${data.datVersion ?? ''}`.trim(),
        hashes: { crc32: row.c.toLowerCase(), ...(row.h ? { sha1: row.h.toLowerCase() } : {}) },
        size: row.s,
      });
    }
    const loaded: LoadedPlatform = { data, map };
    if (isDefaultBase) cache.set(platform, loaded);
    return loaded;
  } catch {
    if (isDefaultBase) cache.set(platform, null);
    return null;
  }
}

/** Load a platform table once; concurrent callers share the in-flight request. */
export function ensurePlatform(platform: PlatformId): Promise<LoadedPlatform | null> {
  if (cache.has(platform)) return Promise.resolve(cache.get(platform)!);
  if (pending.has(platform)) return pending.get(platform)!;
  const p = loadPlatform(platform).finally(() => pending.delete(platform));
  pending.set(platform, p);
  return p;
}

export async function fetchCatalogueIndex(): Promise<CatalogueIndex | null> {
  try {
    const res = await fetch(`${catalogueBase}/index.json`, { cache: 'force-cache' });
    if (!res.ok) return null;
    return (await res.json()) as CatalogueIndex;
  } catch {
    return null;
  }
}

export interface FingerprintInput {
  platform: PlatformId | null;
  size: number;
  crc32: string;
  sha1: string;
  /** Try other platforms when detection was not certain. */
  fallbackPlatforms?: PlatformId[];
}

export interface FingerprintResult {
  match: CatalogueMatch | null;
  /** Platforms that were actually consulted (for transparency in the report). */
  consulted: Array<{ platform: PlatformId; loaded: boolean; count: number }>;
  /** True when the catalogue could not be consulted at all. */
  unavailable: boolean;
}

export async function fingerprint(input: FingerprintInput): Promise<FingerprintResult> {
  const platforms: PlatformId[] = [];
  if (input.platform) platforms.push(input.platform);
  for (const p of input.fallbackPlatforms ?? []) if (!platforms.includes(p)) platforms.push(p);

  const consulted: FingerprintResult['consulted'] = [];
  let anyLoaded = false;

  for (const platform of platforms) {
    const loaded = await ensurePlatform(platform);
    consulted.push({ platform, loaded: Boolean(loaded), count: loaded?.data.count ?? 0 });
    if (!loaded) continue;
    anyLoaded = true;
    const hit =
      loaded.map.get(key(input.size, input.crc32)) ??
      // Some DAT sizes include a copier header; also try the exact SHA-1 scan
      // against the same platform's index when sizes disagree.
      undefined;
    if (hit) {
      const shaMatches = !hit.hashes.sha1 || hit.hashes.sha1 === input.sha1.toLowerCase();
      return {
        match: {
          entryId: hit.id,
          name: hit.title,
          region: hit.region,
          version: hit.version,
          matchedOn: shaMatches ? 'sha1' : 'crc32',
          kind: hit.kind,
          licence: hit.licence,
          source: hit.source,
        },
        consulted,
        unavailable: false,
      };
    }
  }

  return { match: null, consulted, unavailable: !anyLoaded };
}

/** Synchronous lookup used by tests and by the verification pipeline. */
export function lookupLoaded(
  platform: PlatformId,
  size: number,
  crc: string,
): CatalogueEntry | null {
  const loaded = cache.get(platform);
  if (!loaded) return null;
  return loaded.map.get(key(size, crc)) ?? null;
}

export function crcHexOf(bytes: Uint8Array): string {
  return crc32Hex(bytes);
}
